#include <stdio.h>
#include <string.h>
int max(int a, int b) { return a > b ? a : b; }
int main() {
    char s[100005]; int k; if (scanf("%s %d", s, &k) != 2) return 0;
    int counts[26] = {0}, max_freq = 0, l = 0, ans = 0;
    int len = strlen(s);
    for (int r = 0; r < len; r++) {
        counts[s[r] - 'A']++;
        max_freq = max(max_freq, counts[s[r] - 'A']);
        while ((r - l + 1) - max_freq > k) {
            counts[s[l] - 'A']--;
            l++;
        }
        ans = max(ans, r - l + 1);
    }
    printf("%d\n", ans);
    return 0;
}

