                cnt[s.charAt(r) - 'A']++;
                maxFreq = Math.max(maxFreq, cnt[s.charAt(r) - 'A']);
                while ((r - l + 1) - maxFreq > k) {
                    cnt[s.charAt(l) - 'A']--;
                    l++;
                }
                ans = Math.max(ans, r - l + 1);
            }
            System.out.println(ans);
        }
    }
